package com.vuelossanitarios.backend.api;
import com.vuelossanitarios.backend.api.dto.AuditDtos.*;import com.vuelossanitarios.backend.security.CurrentUser;import com.vuelossanitarios.backend.service.AuditQueryService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/audit") public class AuditController {private final AuditQueryService service;public AuditController(AuditQueryService s){service=s;}@GetMapping("/flights/{id}")public AuditPage flight(@PathVariable UUID id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@AuthenticationPrincipal CurrentUser u){return service.byFlight(id,u.id(),page,size);}@GetMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public AuditPage all(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.all(page,size);}}
